var i=`0789-octopus-curry`;var n=`world-0789`;var s=`SC`;var r=`eastern-africa`;var o=4;var a=91;var l={en:`Octopus Curry`,ua:`Карі з восьминога`};var u={en:`Octopus Curry is a Seychelles classic prepared with octopus, bay leaf, yellow onion, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Карі з восьминога, страва кухні країни Сейшельські Острови зі складниками: восьминіг, лавровий лист, жовта цибуля, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Simmer cleaned octopus gently until the thickest tentacle is tender, then cut into bite-sized pieces for the curry.`,ua:`Обережно варіть очищеного восьминога до м’якості товстих щупалець, тоді наріжте шматочками для карі.`,t:[`boiling`],m:50,i:[[`octopus`,800,`g`],[`water`,950,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`curry-powder`,12,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`coconut-milk`,480,`ml`],[`tomato`,260,`g`],[`ground-turmeric`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lime`,1,`pcs`],[`cilantro`,20,`g`]]}];var g={slug:i,id:n,country:`SC`,region:r,servings:4,minutes:91,title:l,text:u,steps:c};export{s as country,g as default,n as id,a as minutes,r as region,o as servings,i as slug,c as steps,u as text,l as title};